import 'package:equatable/equatable.dart';

/// Verification status of an AI observation or downstream assessment.
enum ValidationStatus {
  verified,
  provisional,
  uncertain,
  degraded,
  unavailable,
}

/// Shared provenance attached to observations generated by local models.
class ObservationProvenance extends Equatable {
  const ObservationProvenance({
    required this.observationId,
    required this.timestamp,
    required this.modelId,
    required this.modelVersion,
    required this.confidence,
    required this.inputWidth,
    required this.inputHeight,
    required this.processingDurationMs,
    required this.sourceCapability,
    required this.validationStatus,
  });

  final String observationId;
  final DateTime timestamp;
  final String modelId;
  final String modelVersion;
  final double confidence;
  final int inputWidth;
  final int inputHeight;
  final int processingDurationMs;
  final String sourceCapability;
  final ValidationStatus validationStatus;

  @override
  List<Object?> get props => [
        observationId,
        timestamp,
        modelId,
        modelVersion,
        confidence,
        inputWidth,
        inputHeight,
        processingDurationMs,
        sourceCapability,
        validationStatus,
      ];
}

/// Image quality metrics computed on-device prior to or alongside inference.
class ImageQualityMetrics extends Equatable {
  const ImageQualityMetrics({
    required this.meanLuma,
    required this.lumaStdDev,
    required this.laplacianVariance,
    required this.overexposedRatio,
    required this.underexposedRatio,
    this.cameraPitchDegrees,
  });

  final double meanLuma;
  final double lumaStdDev;
  final double laplacianVariance;
  final double overexposedRatio;
  final double underexposedRatio;
  final double? cameraPitchDegrees;

  bool get isTooDark => meanLuma < 28.0 || underexposedRatio > 0.72;
  bool get isTooBlurry => laplacianVariance < 35.0;
  bool get hasSevereGlare => overexposedRatio > 0.45;
  bool get isDegraded => isTooDark || isTooBlurry || hasSevereGlare;

  List<String> get degradationReasons {
    final reasons = <String>[];
    if (isTooDark) reasons.add('low lighting');
    if (isTooBlurry) reasons.add('camera blur or motion');
    if (hasSevereGlare) reasons.add('excessive glare or overexposure');
    return reasons;
  }

  static const ImageQualityMetrics nominal = ImageQualityMetrics(
    meanLuma: 128.0,
    lumaStdDev: 48.0,
    laplacianVariance: 160.0,
    overexposedRatio: 0.02,
    underexposedRatio: 0.03,
  );

  @override
  List<Object?> get props => [
        meanLuma,
        lumaStdDev,
        laplacianVariance,
        overexposedRatio,
        underexposedRatio,
        cameraPitchDegrees,
      ];
}
